using System;
using System.Collections.Generic;

namespace RiskOfCSharp2.Data
{
    public class LoreRecord
    {
        public string Header = "";      // e.g. "ПРОТОКОЛ ДОСТАВКИ UES #0419 // ДАТА: 14.08.2056" or "ПОЛЕВОЙ ЖУРНАЛ НАТУРАЛИСТА"
        public string Quote = "";       // Atmospheric in-universe epigraph / quote in Russian
        public string Body = "";        // Rich 2-3 paragraph lore entry in Russian (separated by \n\n)
        public string ExtraNotes = "";  // Additional archive notes / origin / tactical observations in Russian
    }

    public static partial class LoreDatabase
    {
        // Key format: "{category}:{key}", e.g. "items:syringe", "survivors:sol", "monsters:lemurian", "bosses:mithrix", "stages:roost", "achievements:ach_slayer", "modifiers:monsoon"
        public static readonly Dictionary<string, LoreRecord> Records = new();

        public static LoreRecord GetLore(string category, string key)
        {
            string cat = (category ?? "").Trim().ToLowerInvariant();
            string k = (key ?? "").Trim().ToLowerInvariant();

            if (!string.IsNullOrEmpty(cat) && !string.IsNullOrEmpty(k))
            {
                if (Records.TryGetValue($"{cat}:{k}", out var direct))
                    return direct;

                if (cat == "monsters" && Records.TryGetValue($"bosses:{k}", out var asBoss))
                    return asBoss;

                if (cat == "bosses" && Records.TryGetValue($"monsters:{k}", out var asMonster))
                    return asMonster;
            }
            else if (string.IsNullOrEmpty(cat) && k.Contains(':') && Records.TryGetValue(k, out var combined))
            {
                return combined;
            }

            return new LoreRecord
            {
                Header = $"АРХИВНЫЙ ТЕРМИНАЛ UES // СЕКТОР [{cat.ToUpperInvariant()}:{k.ToUpperInvariant()}]",
                Quote = "«Некоторые страницы бортового журнала оплавились при входе в атмосферу Petrichor V, но память выживших хранит больше, чем сталь».",
                Body = "Запрошенная запись прошла через гравитационную бурю орбитального разлома и частично утратила телеметрию при падении грузовых отсеков UES «Contact Light».\n\nПолевые исследователи продолжают собирать обломки чёрных ящиков и восстанавливать зашифрованные свидетельства о природе этой аномалии.",
                ExtraNotes = "СТАТУС ЗАПИСИ: Резервная реконструкция терминала UES «Safe Travels»."
            };
        }

        private static void Add(string fullKey, string header, string quote, string body, string extraNotes)
        {
            Records[fullKey] = new LoreRecord
            {
                Header = header,
                Quote = quote,
                Body = body,
                ExtraNotes = extraNotes
            };
        }

        static LoreDatabase()
        {
            InitializeItemsWhite();
            InitializeItemsGreen();
            InitializeItemsRedVoidLunar();
            InitializeSurvivorsPart1();
            InitializeSurvivorsPart2();
            InitializeAltSurvivors();
            InitializeMonstersAndBosses();
            InitializeStagesAndModifiers();
            InitializeItemAchievements();
            InitializeCharacterAchievements();
        }

