            Add("items:rabadons_deathcap",
                "МЕЖПРОСТРАНСТВЕННЫЙ ПЕРЕХВАТ UES #1008 // ИСТОЧНИК: ВЕРХОВНЫЙ КОНКЛАВ АРКАНЫ (РУНЕТЕРРА)",
                "«Когда ты надеваешь венец Рабадона, заклинания перестают просить разрешения у законов мироздания».",
                "Высокая остроконечная шляпа из багрового бархата с изогнутыми полями и золотой пряжкой-оком, которая смотрит прямо сквозь ткань реальности. Внутри тульи вытканы концентрические спирали абсолютного магического умножения.\n\nДаже далекий от чародейства десантник, примерив этот венец, ощущает, как воздух вокруг его ладоней и стволов наливается гудящей разрушительной мощью. Каждая пуля, взрыв, молния и сокрушительный ультимейт возрастают в своей убойной силе на треть без каких-либо компромиссов.\n\nВенец архимага признаёт только одну меру совершенства — тотальное превосходство огневой и духовной мощи.",
                "КРОССОВЕР-АРТЕФАКТ [League of Legends] // ТАКТИЧЕСКАЯ ЗАМЕТКА: Глобальный мультипликатор мощи — увеличивает весь наносимый урон всех атак и способностей на +35%.");

            Add("items:infinity_edge",
                "МЕЖПРОСТРАНСТВЕННЫЙ ПЕРЕХВАТ UES #1009 // ИСТОЧНИК: ДРЕВНИЕ ПЕСКИ ШУРИМЫ И ДЕМАСИИ",
                "«Между тяжёлым ранением и мгновенным небытием лежит тонкая золотая грань. Этот меч выкован целиком из неё».",
                "Величественный золотой клинок с расходящимся солнечным лезвием и сапфировым ядром в перекрестье гарды. Его режущая кромка не просто заточена — она сведена до толщины геометрической линии, рассекающей саму причинность.\n\nОружие возводит искусство критического удара в абсолют: оно не только помогает чаще находить смертельные бреши в броне чудовищ, но и наделяет каждый критический выпад сокрушительной, полуторакратной прибавкой к разрушению.\n\nВ сочетании с полным набором оптики Часовщика Грань Бесконечности превращает каждую атаку в золотую вспышку окончательного приговора.",
                "КРОССОВЕР-АРТЕФАКТ [League of Legends] // ТАКТИЧЕСКАЯ ЗАМЕТКА: Даёт +15% шанса крита и резко увеличивает множитель критического урона на +45%.");

            Add("items:zhonyas_hourglass",
                "МЕЖПРОСТРАНСТВЕННЫЙ ПЕРЕХВАТ UES #1010 // ИСТОЧНИК: ХРАНИЛИЩА ВРЕМЕНИ ИОНИИ И БЛАГОСЛОВЕННЫХ ОСТРОВОВ",
                "«Пусть рушится небо и плавится камень под ногами — две с половиной секунды вечности принадлежат только тебе».",
                "Парящие в кольцевом золотом каркасе песочные часы, внутри которых вместо кварца пересыпается сияющая солнечная пыль застывших мгновений. Стекло сосуда не поддаётся ни молоту, ни жару магмы.\n\nВ тот роковой миг, когда здоровье носителя падает до опасного предела и следующий когтевой удар должен стать смертельным, часы автоматически переворачиваются с чистым хрустальным звоном. Тело героя обращается в несокрушимую золотую статую вне потока времени: все вражеские лучи и взрывы бессильно омывают сияющий металл, пока внутренний свет залечивает раны и возводит щит.\n\nВыходя из золотого стазиса обновлённым, выживший получает второй шанс переломить исход самой безнадёжной битвы.",
