            Add("items:plasma_shrimp",
                "КАТАЛОГ ЯЧЕЙКИ ПУСТОТЫ // ОБРАЗЕЦ СИМБИОЗА #V-014 (ИСКАЖЁННЫЙ КОМПЛЕКС AtG)",
                "«Оно съело ракетную установку изнутри, оставив только панцирь и голод. Не вздумай терять щит — оно не любит оставаться голым».",
                "Глубоководное ракообразное из фиолетово-чёрного хитина Бездны, намертво вросшее своими жвалами в оплавленные остатки наплечной ракетницы. Вдоль сегментированного хвоста симбионта переливаются ярко-пурпурные сгустки нестабильной плазмы.\n\nВ отличие от земной электроники, стреляющей от случая к случаю, порождение Пустоты откликается со стопроцентной безотказностью — но требует взамен постоянного энергетического кокона. Пока тело хозяина укрыто хотя бы тончайшей плёнкой силового щита, каждый без исключения выстрел сопровождается роем визжащих фиолетовых микроракет.\n\nХолодный взгляд бусинчатых глаз креветки словно напоминает: мы защищаем друг друга лишь до тех пор, пока ты держишь барьер.",
                "КАТЕГОРИЯ: Симбионт Пустоты // ТАКТИЧЕСКАЯ ЗАМЕТКА: Даёт постоянный щит и гарантированно выпускает плазменную ракету при КАЖДОЙ атаке, пока щит активен.");

            Add("items:polylute",
                "КАТАЛОГ ЯЧЕЙКИ ПУСТОТЫ // ОБРАЗЕЦ СИМБИОЗА #V-027 (ИСКАЖЁННАЯ УКУЛЕЛЕ)",
                "«...и его музыка звучала... нет. Из глубин океана не доносится песен — только глухой треск сжимаемых панцирей».",
                "Причудливый многорукавный струнный инструмент, чей деревянный корпус оброс кальциевыми наростами глубоководных полипов и фиолетовыми щупальцами Пустоты. Натянутые жилы издают при касании не мелодичный аккорд, а низкий вибрирующий гул тектонической впадины.\n\nТам, где прежняя укулеле рассеивала молнию по всей округе, Полилютня собирает всю ярость грозы в одну-единственную точку пространства. Вместо широкой дуги она обрушивает прямо в череп выбранной жертвы серию сосредоточенных фиолетовых разрядов Бездны.\n\nПротив одиночных исполинов и владык Луны эта мрачная симфония звучит куда смертоноснее любой земной баллады.",
                "КАТЕГОРИЯ: Искажённая реликвия Пустоты // ТАКТИЧЕСКАЯ ЗАМЕТКА: Вместо рассеивания по толпе обрушивает концентрированный каскад ударов молнии Бездны в одну цель.");

            Add("items:safer_spaces",
                "КАТАЛОГ ЯЧЕЙКИ ПУСТОТЫ // ОБРАЗЕЦ СИМБИОЗА #V-039 (ИСКАЖЁННЫЙ МИШКА)",
                "«Зачем надеяться на капризную удачу игрушки, когда можно вырезать себя из пространства ровно на долю секунды удара?»",
                "Потрёпанная плюшевая оболочка медвежонка, внутри которой вместо ваты вращается холодная сфера свёрнутого вакуума Бездны. Вокруг носителя предмета образуется полупрозрачный лиловый пузырь искривлённой геометрии.\n\nПустота презирает случайность. Этот аномальный кокон не бросает кости судьбы: он гарантированно поглощает в небытие абсолютно любой — даже самый чудовищный — вражеский удар, а затем спокойно восстанавливает свою мембрану через строго отмеренный промежуток времени.\n\nВыжившие быстро привыкают к тихому хлопку схлопывающейся сферы как к метроному абсолютной безопасности.",
                "КАТЕГОРИЯ: Пространственный паразит Пустоты // ТАКТИЧЕСКАЯ ЗАМЕТКА: 100% гарантированный блок любого входящего удара раз в 12 секунд (перезарядка снижается за каждый стак).");

            Add("items:lysate_cell",
                "КАТАЛОГ ЯЧЕЙКИ ПУСТОТЫ // ОБРАЗЕЦ СИМБИОЗА #V-052 (БИОРЕАКТОР БЕЗДНЫ)",
                "«Клетка делится быстрее, чем остывает ствол. Главное — не смотреть слишком долго, как внутри неё шевелится фиолетовый свет».",
                "Органический топливный цилиндр из полупрозрачного рогового панциря, заполненный кипящим пурпурным лизатом — клеточным экстрактом существ, обитающих на самом дне межмирового океана Пустоты.\n\nПодсоединяясь к главному энергетическому контуру костюма, биоячейка переводит ультимативную способность владельца на сверхбыстрый цикл регенерации заряда. То, что прежде требовало долгой подготовки и накопления сил, теперь обрушивается на поле боя снова и снова с пугающей частотой.\n\nОт корпуса ячейки исходит едва слышное бульканье, точно в такт дыханию своего нового хозяина.",
                "КАТЕГОРИЯ: Энергоячейка Пустоты // ТАКТИЧЕСКАЯ ЗАМЕТКА: Сокращает время перезарядки Ультимейта [R] на 25% за каждый собранный экземпляр.");

